#pragma warning disable CA1725,CA1862
public sealed partial class InventoryAdministration(CoreDbContext db,ITransactionExecutor tx,ICompanyContext company,ICurrentActor actor,ICorrelationContext correlation,IAuditWriter audit,TimeProvider time,IOrderPricingEngine pricing):IInventoryAdministration,IPurchasingAdministration
{
 private Guid Company=>company.RequireCompanyId();private Guid Actor=>Guid.TryParse(actor.Actor.UserId,out Guid id)?id:throw new InvalidOperationException("Authenticated actor required.");private DateTimeOffset Now=>time.GetUtcNow();private string Correlation=>correlation.CorrelationId??Guid.NewGuid().ToString("N");
 public Task<Result<IReadOnlyList<StockBalanceView>>>BalancesAsync(Guid?w,Guid?v,CancellationToken ct)=>tx.ExecuteAsync(async t=>{IQueryable<StockBalance>q=db.StockBalances.AsNoTracking();if(w is not null)q=q.Where(x=>x.WarehouseId==w);if(v is not null)q=q.Where(x=>x.ProductVariantId==v);return Result.Success<IReadOnlyList<StockBalanceView>>((await q.OrderBy(x=>x.WarehouseId).ThenBy(x=>x.ProductVariantId).ToListAsync(t)).Select(BalanceView).ToArray());},ct);
 public Task<Result<IReadOnlyList<StockTransactionView>>>TransactionsAsync(Guid?w,Guid?v,CancellationToken ct)=>tx.ExecuteAsync(async t=>{IQueryable<StockTransaction>q=db.StockTransactions.AsNoTracking();if(w is not null)q=q.Where(x=>x.WarehouseId==w);if(v is not null)q=q.Where(x=>x.ProductVariantId==v);return Result.Success<IReadOnlyList<StockTransactionView>>((await q.OrderByDescending(x=>x.OccurredAtUtc).Take(500).ToListAsync(t)).Select(TransactionView).ToArray());},ct);
 public Task<Result<IReadOnlyList<ReturnableIssueView>>>ReturnableIssuesAsync(CancellationToken ct)=>tx.ExecuteAsync(async t=>{List<StockTransaction>issues=await db.StockTransactions.AsNoTracking().Where(x=>x.SourceType=="WAREHOUSE_ISSUE"&&x.TransactionType==StockTransactionType.Issue).OrderByDescending(x=>x.OccurredAtUtc).Take(500).ToListAsync(t);List<Guid> ids=issues.Where(x=>x.SourceId is not null).Select(x=>x.SourceId!.Value).ToList();Dictionary<Guid,StockReservation> reservations=await db.StockReservations.AsNoTracking().Where(x=>ids.Contains(x.Id)).ToDictionaryAsync(x=>x.Id,t);List<StockTransaction> returns=await db.StockTransactions.AsNoTracking().Where(x=>x.TransactionType==StockTransactionType.Return&&x.SourceId!=null&&ids.Contains(x.SourceId.Value)).ToListAsync(t);Dictionary<Guid,Guid> itemOrders=await db.OrderItems.AsNoTracking().Where(x=>reservations.Values.Select(r=>r.OrderItemId).Contains(x.Id)).ToDictionaryAsync(x=>x.Id,x=>x.OrderId,t);return Result.Success<IReadOnlyList<ReturnableIssueView>>(issues.Select(x=>{decimal issued=Math.Abs(x.QuantityDelta),returned=returns.Where(y=>y.SourceId==x.Id).Sum(y=>y.QuantityDelta);reservations.TryGetValue(x.SourceId??Guid.Empty,out StockReservation? r);Guid? item=r?.OrderItemId;return new ReturnableIssueView(x.Id,item is Guid itemId&&itemOrders.TryGetValue(itemId,out Guid order)?order:null,item,x.WarehouseId,x.ProductVariantId,x.UomCode,issued,returned,Math.Max(0,issued-returned),x.Reference,x.OccurredAtUtc);}).Where(x=>x.RemainingQuantity>0).ToArray());},ct);
 public Task<Result<IReadOnlyList<StockShortageView>>>ShortagesAsync(bool includeClosed,int limit,CancellationToken ct)=>tx.ExecuteAsync(async t=>{IQueryable<StockShortage>q=db.StockShortages.AsNoTracking();if(!includeClosed)q=q.Where(x=>x.IsActive);return Result.Success<IReadOnlyList<StockShortageView>>((await q.OrderByDescending(x=>x.CreatedAtUtc).Take(limit).ToListAsync(t)).Select(x=>new StockShortageView(x.Id,x.OrderItemId,x.WarehouseId,x.ProductVariantId,x.RequiredQuantity,x.AvailableQuantity,x.ShortageQuantity,x.IsActive,x.CreatedAtUtc,x.Version)).ToArray());},ct);
 public Task<Result<IReadOnlyList<ReservationView>>>ReservationsAsync(bool includeClosed,int limit,CancellationToken ct)=>tx.ExecuteAsync(async t=>{IQueryable<StockReservation>q=db.StockReservations.AsNoTracking();if(!includeClosed)q=q.Where(x=>x.Status==ReservationStatus.Active||x.Status==ReservationStatus.PartiallyReleased);return Result.Success<IReadOnlyList<ReservationView>>( (await q.OrderByDescending(x=>x.CreatedAtUtc).Take(limit).ToListAsync(t)).Select(ReservationView).ToArray());},ct);
 public Task<Result<StockTransactionView>>ReceiveAsync(StockMovementCommand c,CancellationToken ct)=>tx.ExecuteAsync(async t=>await Movement(c,StockTransactionType.Receipt,Math.Abs(c.Quantity),false,"MANUAL_RECEIPT",null,t),ct);
 public Task<Result<StockTransactionView>>IssueAsync(StockMovementCommand c,StockTransactionType type,CancellationToken ct)=>tx.ExecuteAsync(async t=>type is not(StockTransactionType.Issue or StockTransactionType.Scrap or StockTransactionType.Return)?Result.Failure<StockTransactionView>(InventoryErrors.InvalidData):await Movement(c,type,-Math.Abs(c.Quantity),false,"MANUAL_ISSUE",null,t),ct);
 public Task<Result<StockTransactionView>>AdjustAsync(StockMovementCommand c,bool increase,CancellationToken ct)=>tx.ExecuteAsync(async t=>string.IsNullOrWhiteSpace(c.ReasonCode)?Result.Failure<StockTransactionView>(InventoryErrors.ReasonRequired):await Movement(c,StockTransactionType.Adjustment,(increase?1:-1)*Math.Abs(c.Quantity),false,"ADJUSTMENT",null,t),ct);
 public Task<Result<ReserveStockResult>>ReserveAsync(ReserveStockCommand c,CancellationToken ct)=>tx.ExecuteAsync(async t=>
 {if(c.Quantity<=0||string.IsNullOrWhiteSpace(c.IdempotencyKey))return Result.Failure<ReserveStockResult>(InventoryErrors.InvalidData);StockReservation?duplicate=await db.StockReservations.SingleOrDefaultAsync(x=>x.IdempotencyKey==c.IdempotencyKey.Trim(),t);if(duplicate is not null)return Result.Success(new ReserveStockResult(ReservationView(duplicate),null,0,0));var item=await db.OrderItems.AsNoTracking().SingleOrDefaultAsync(x=>x.Id==c.OrderItemId&&x.IsActive,t);if(item is null||item.ProductVariantId==Guid.Empty||!await ValidWarehouseVariant(c.WarehouseId,item.ProductVariantId,t))return Result.Failure<ReserveStockResult>(InventoryErrors.NotFound);string uom=await Uom(item.ProductVariantId,t);if(!string.IsNullOrWhiteSpace(c.UomCode)&&!string.Equals(InventoryText.Code(c.UomCode),uom,StringComparison.OrdinalIgnoreCase))return Result.Failure<ReserveStockResult>(InventoryErrors.UnitMismatch);StockBalance?b=await LockBalance(c.WarehouseId,item.ProductVariantId,t);decimal available=b?.Available??0;if(b is null||available<c.Quantity){StockShortage?shortage=await db.StockShortages.SingleOrDefaultAsync(x=>x.OrderItemId==c.OrderItemId&&x.WarehouseId==c.WarehouseId&&x.IsActive,t);if(shortage is null){shortage=StockShortage.Create(Company,c.OrderItemId,c.WarehouseId,item.ProductVariantId,c.Quantity,available,Now);db.Add(shortage);Log("inventory.shortage.created",shortage.Id);}return Result.Success(new ReserveStockResult(null,shortage.Id,available,Math.Max(0,c.Quantity-available)));}Result reserved=b.Reserve(c.Quantity,Now);if(reserved.IsFailure)return Result.Failure<ReserveStockResult>(reserved.Error);StockReservation r=StockReservation.Create(Company,c.OrderItemId,c.WarehouseId,item.ProductVariantId,uom,c.Quantity,c.ExpiresAtUtc,c.IdempotencyKey,Now);db.Add(r);Log("inventory.reservation.created",r.Id);return Result.Success(new ReserveStockResult(ReservationView(r),null,b.Available,0));},ct);
 public Task<Result<ReservationView>>ReleaseAsync(Guid id,ReleaseReservationCommand c,CancellationToken ct)=>tx.ExecuteAsync(async t=>{StockReservation?r=await LockReservation(id,t);if(r is null)return Result.Failure<ReservationView>(InventoryErrors.NotFound);StockBalance?b=await LockBalance(r.WarehouseId,r.ProductVariantId,t);if(b is null)return Result.Failure<ReservationView>(InventoryErrors.NotFound);Result release=r.Release(c.Quantity,c.Version,Now);if(release.IsFailure)return Result.Failure<ReservationView>(release.Error);Result br=b.Release(c.Quantity,Now);if(br.IsFailure)return Result.Failure<ReservationView>(br.Error);Log("inventory.reservation.released",r.Id);return Result.Success(ReservationView(r));},ct);
 public Task<Result<ReservationView>>IssueReservedAsync(Guid id,IssueReservationCommand c,CancellationToken ct)=>tx.ExecuteAsync(async t=>{StockReservation?r=await LockReservation(id,t);if(r is null)return Result.Failure<ReservationView>(InventoryErrors.NotFound);StockBalance?b=await LockBalance(r.WarehouseId,r.ProductVariantId,t);if(b is null)return Result.Failure<ReservationView>(InventoryErrors.NotFound);if(await db.StockTransactions.AnyAsync(x=>x.Reference==InventoryText.Code(c.Reference),t))return Result.Success(ReservationView(r));Result cr=r.Consume(c.Quantity,c.Version,Now);if(cr.IsFailure)return Result.Failure<ReservationView>(cr.Error);Result cb=b.Consume(c.Quantity,Now);if(cb.IsFailure)return Result.Failure<ReservationView>(cb.Error);string uom=await Uom(r.ProductVariantId,t);StockTransaction st=StockTransaction.Create(Company,r.WarehouseId,r.ProductVariantId,StockTransactionType.Issue,-c.Quantity,uom,"RESERVATION",r.Id,c.Reference,"RESERVED_ISSUE",Actor,Correlation,Now,Now).Value;db.Add(st);Log("inventory.reservation.consumed",r.Id);Log("inventory.stock.issued",st.Id);return Result.Success(ReservationView(r));},ct);
 public Task<Result<IssueOrderInventoryResult>>IssueOrderAsync(IssueOrderInventoryCommand c,CancellationToken ct)=>tx.ExecuteAsync(t=>IssueOrderInsideTransactionAsync(c,t),ct);
 public async Task<Result<IssueOrderInventoryResult>> IssueOrderInsideTransactionAsync(IssueOrderInventoryCommand c,CancellationToken t)
 {
  if(c.OrderId==Guid.Empty||c.WarehouseId==Guid.Empty||string.IsNullOrWhiteSpace(c.Reference)||c.Items.Count==0||c.Items.Any(x=>x.OrderItemId==Guid.Empty||x.Quantity<=0)||c.Items.Select(x=>x.OrderItemId).Distinct().Count()!=c.Items.Count)return Result.Failure<IssueOrderInventoryResult>(InventoryErrors.InvalidData);
  string reference=InventoryText.Code(c.Reference); List<StockReservation> rows=await db.StockReservations.Where(x=>x.CompanyId==Company&&x.OrderItemId!=Guid.Empty&&c.Items.Select(i=>i.OrderItemId).Contains(x.OrderItemId)&&x.WarehouseId==c.WarehouseId).OrderBy(x=>x.Id).ToListAsync(t);
  Dictionary<Guid,IssueOrderItemCommand> requested=c.Items.ToDictionary(x=>x.OrderItemId); List<StockTransaction> existing=await db.StockTransactions.Where(x=>x.CompanyId==Company&&x.Reference.StartsWith(reference+":")).OrderBy(x=>x.Reference).ToListAsync(t);
  if(existing.Count>0)
  {
   if(existing.Count!=c.Items.Count||existing.Any(x=>!requested.TryGetValue(x.SourceId is Guid sid&&rows.FirstOrDefault(r=>r.Id==sid)?.OrderItemId is Guid item?item:Guid.Empty,out var q)||Math.Abs(x.QuantityDelta)!=q.Quantity))return Result.Failure<IssueOrderInventoryResult>(InventoryErrors.DuplicateReference);
   return Result.Success(new IssueOrderInventoryResult(c.OrderId,c.WarehouseId,reference,rows.Select(ReservationView).ToArray(),existing.Select(TransactionView).ToArray()));
  }
  if(!await db.Orders.AnyAsync(x=>x.Id==c.OrderId&&x.CompanyId==Company&&x.Status==BARANG.Core.Domain.Orders.OrderStatus.Submitted,t))return Result.Failure<IssueOrderInventoryResult>(InventoryErrors.InvalidTransition);
  List<StockReservation> locked=[];
  foreach(IssueOrderItemCommand item in c.Items.OrderBy(x=>x.OrderItemId)){StockReservation? row=await LockReservationForOrder(item.OrderItemId,c.OrderId,c.WarehouseId,t);if(row is null)return Result.Failure<IssueOrderInventoryResult>(InventoryErrors.NotFound);if(item.Quantity>row.RemainingQuantity)return Result.Failure<IssueOrderInventoryResult>(InventoryErrors.Insufficient);string uom=await Uom(row.ProductVariantId,t);if(!string.IsNullOrWhiteSpace(item.UomCode)&&InventoryText.Code(item.UomCode)!=uom)return Result.Failure<IssueOrderInventoryResult>(InventoryErrors.UnitMismatch);locked.Add(row);}
  List<(Guid Variant,string Uom)> keys=locked.Select(x=>(Variant:x.ProductVariantId,Uom:x.UomCode)).Distinct().OrderBy(x=>x.Variant).ThenBy(x=>x.Uom).ToList();Dictionary<(Guid,string),StockBalance> balances=[];foreach((Guid Variant,string Uom) key in keys){StockBalance? b=await LockBalance(c.WarehouseId,key.Variant,t);if(b is null)return Result.Failure<IssueOrderInventoryResult>(InventoryErrors.NotFound);balances[key]=b;}
  List<StockTransaction> made=[];foreach((StockReservation row,IssueOrderItemCommand item) in locked.Zip(c.Items.OrderBy(x=>x.OrderItemId))){Result consumed=row.Consume(item.Quantity,row.Version,Now);if(consumed.IsFailure)return Result.Failure<IssueOrderInventoryResult>(consumed.Error);Result stock=balances[(row.ProductVariantId,row.UomCode)].Consume(item.Quantity,Now);if(stock.IsFailure)return Result.Failure<IssueOrderInventoryResult>(stock.Error);Result<StockTransaction> created=StockTransaction.Create(Company,row.WarehouseId,row.ProductVariantId,StockTransactionType.Issue,-item.Quantity,row.UomCode,"WAREHOUSE_ISSUE",row.Id,$"{reference}:{row.Id:N}","ORDER_ISSUE",Actor,Correlation,Now,Now);if(created.IsFailure)return Result.Failure<IssueOrderInventoryResult>(created.Error);db.Add(created.Value);made.Add(created.Value);Log("inventory.stock.issued",created.Value.Id);}
  return Result.Success(new IssueOrderInventoryResult(c.OrderId,c.WarehouseId,reference,locked.Select(ReservationView).ToArray(),made.Select(TransactionView).ToArray()));
 }
 public Task<Result<AdjustOrderInventoryResult>> AdjustOrderAsync(AdjustOrderInventoryCommand c,CancellationToken ct)=>tx.ExecuteAsync(t=>AdjustOrderInsideTransactionAsync(c,t),ct);
 private async Task<Result<AdjustOrderInventoryResult>> AdjustOrderInsideTransactionAsync(AdjustOrderInventoryCommand c,CancellationToken t)
 {
  if(c.OrderId==Guid.Empty||c.OrderVersion<1||string.IsNullOrWhiteSpace(c.RequestKey)||c.Items.Count==0||c.Items.Any(x=>x.OrderItemId==Guid.Empty||x.ProductId==Guid.Empty||x.ProductVariantId==Guid.Empty||x.WarehouseId==Guid.Empty||x.Quantity<=0)||c.Items.Select(x=>x.OrderItemId).Distinct().Count()!=c.Items.Count)return Result.Failure<AdjustOrderInventoryResult>(InventoryErrors.InvalidData);
  await db.Database.ExecuteSqlInterpolatedAsync($"SELECT id FROM barang.orders WHERE company_id={Company} AND id={c.OrderId} FOR UPDATE",t);
  var order=await db.Orders.SingleOrDefaultAsync(x=>x.CompanyId==Company&&x.Id==c.OrderId,t);if(order is null)return Result.Failure<AdjustOrderInventoryResult>(InventoryErrors.NotFound);if(order.Status!=BARANG.Core.Domain.Orders.OrderStatus.Submitted)return Result.Failure<AdjustOrderInventoryResult>(InventoryErrors.InvalidTransition);
  string requestKey=InventoryText.Code(c.RequestKey);List<StockReservation> replay=await db.StockReservations.Where(x=>x.CompanyId==Company&&x.IdempotencyKey.StartsWith(requestKey+":")).ToListAsync(t);if(replay.Count>0){bool same=replay.Count==c.Items.Count&&c.Items.All(i=>replay.Any(r=>r.OrderItemId==i.OrderItemId&&r.WarehouseId==i.WarehouseId&&r.ProductVariantId==i.ProductVariantId&&r.RequestedQuantity==i.Quantity&&string.IsNullOrWhiteSpace(i.UomCode)||r.OrderItemId==i.OrderItemId&&r.WarehouseId==i.WarehouseId&&r.ProductVariantId==i.ProductVariantId&&r.RequestedQuantity==i.Quantity&&r.UomCode==InventoryText.Code(i.UomCode)));if(!same)return Result.Failure<AdjustOrderInventoryResult>(InventoryErrors.DuplicateReference);return Result.Success(new AdjustOrderInventoryResult(c.OrderId,order.Version,replay.Select(ReservationView).ToArray()));}if(order.Version!=c.OrderVersion)return Result.Failure<AdjustOrderInventoryResult>(InventoryErrors.Concurrency);
  List<BARANG.Core.Domain.Orders.OrderItem> current=await db.OrderItems.Where(x=>x.OrderId==c.OrderId&&x.IsActive).OrderBy(x=>x.Id).ToListAsync(t);if(current.Count!=c.Items.Count||current.Any(x=>!c.Items.Any(y=>y.OrderItemId==x.Id)))return Result.Failure<AdjustOrderInventoryResult>(InventoryErrors.InvalidData);
  Dictionary<Guid,AdjustOrderItemCommand> requested=c.Items.ToDictionary(x=>x.OrderItemId);List<StockReservation> old=[];
  foreach(var item in current){var a=requested[item.Id];var variant=await db.ProductVariants.SingleOrDefaultAsync(x=>x.CompanyId==Company&&x.Id==a.ProductVariantId&&x.ProductId==a.ProductId&&x.IsActive,t);if(variant is null)return Result.Failure<AdjustOrderInventoryResult>(InventoryErrors.NotFound);if(!await ValidWarehouseVariant(a.WarehouseId,a.ProductVariantId,t))return Result.Failure<AdjustOrderInventoryResult>(InventoryErrors.NotFound);string uom=await Uom(a.ProductVariantId,t);if(!string.IsNullOrWhiteSpace(a.UomCode)&&InventoryText.Code(a.UomCode)!=uom)return Result.Failure<AdjustOrderInventoryResult>(InventoryErrors.UnitMismatch);StockReservation? r=await db.StockReservations.Where(x=>x.CompanyId==Company&&x.OrderItemId==item.Id&&(x.Status==ReservationStatus.Active||x.Status==ReservationStatus.PartiallyReleased)).OrderByDescending(x=>x.CreatedAtUtc).FirstOrDefaultAsync(t);if(r is not null){await db.Database.ExecuteSqlInterpolatedAsync($"SELECT id FROM barang.stock_reservations WHERE company_id={Company} AND id={r.Id} FOR UPDATE",t);if(await db.StockTransactions.AnyAsync(x=>x.SourceId==r.Id&&x.TransactionType==StockTransactionType.Issue,t))return Result.Failure<AdjustOrderInventoryResult>(InventoryErrors.IssuedItemImmutable);old.Add(r);}}
  string key=requestKey;if(key.Length is <1 or>100)return Result.Failure<AdjustOrderInventoryResult>(InventoryErrors.InvalidData);
  foreach(var item in old.OrderBy(x=>x.WarehouseId).ThenBy(x=>x.ProductVariantId).ThenBy(x=>x.Id)){StockBalance? b=await LockBalance(item.WarehouseId,item.ProductVariantId,t);if(b is null)return Result.Failure<AdjustOrderInventoryResult>(InventoryErrors.NotFound);decimal outstanding=item.RemainingQuantity;Result released=item.Release(outstanding,item.Version,Now);if(released.IsFailure)return Result.Failure<AdjustOrderInventoryResult>(released.Error);Result br=b.Release(outstanding,Now);if(br.IsFailure)return Result.Failure<AdjustOrderInventoryResult>(br.Error);}
  var targetKeys=c.Items.GroupBy(x=>(x.WarehouseId,x.ProductVariantId)).Select(g=>new{g.Key,Quantity=g.Sum(x=>x.Quantity)}).OrderBy(x=>x.Key.WarehouseId).ThenBy(x=>x.Key.ProductVariantId).ToList();Dictionary<(Guid WarehouseId,Guid ProductVariantId),StockBalance> balances=[];
  foreach(var target in targetKeys){StockBalance? b=await LockBalance(target.Key.WarehouseId,target.Key.ProductVariantId,t);if(b is null||b.Available<target.Quantity)return Result.Failure<AdjustOrderInventoryResult>(InventoryErrors.Insufficient);balances[target.Key]=b;}
  List<StockReservation> made=[];foreach(var item in c.Items.OrderBy(x=>x.OrderItemId)){var entity=current.Single(x=>x.Id==item.OrderItemId);string uom=await Uom(item.ProductVariantId,t);Result changed=entity.ChangeInventoryIdentity(item.ProductId,item.ProductVariantId,item.Quantity,Now);if(changed.IsFailure)return Result.Failure<AdjustOrderInventoryResult>(changed.Error);var b=balances[(item.WarehouseId,item.ProductVariantId)];Result reserved=b.Reserve(item.Quantity,Now);if(reserved.IsFailure)return Result.Failure<AdjustOrderInventoryResult>(reserved.Error);var r=StockReservation.Create(Company,item.OrderItemId,item.WarehouseId,item.ProductVariantId,uom,item.Quantity,null,$"{key}:{item.OrderItemId:N}",Now);db.Add(r);made.Add(r);}
  Result<OrderPricingView> revised=await pricing.CalculateInsideTransactionAsync(order,false,null,t,true);if(revised.IsFailure)return Result.Failure<AdjustOrderInventoryResult>(revised.Error);Result touched=order.MarkInventoryAdjusted(Now);if(touched.IsFailure)return Result.Failure<AdjustOrderInventoryResult>(touched.Error);
  return Result.Success(new AdjustOrderInventoryResult(c.OrderId,order.Version,made.Select(ReservationView).ToArray()));
 }
 public Task<Result<StockTransactionView>> ReturnAsync(ReturnStockCommand c,CancellationToken ct)=>tx.ExecuteAsync(async t=>
 {
  if(c.OriginalIssueTransactionId==Guid.Empty||c.Quantity<=0||string.IsNullOrWhiteSpace(c.Reference)||!string.Equals(InventoryText.Code(c.Disposition),"USABLE",StringComparison.Ordinal))return Result.Failure<StockTransactionView>(InventoryErrors.InvalidData);
  string reference=InventoryText.Code(c.Reference);StockTransaction? duplicate=await db.StockTransactions.SingleOrDefaultAsync(x=>x.CompanyId==Company&&x.Reference==reference,t);if(duplicate is not null)return Result.Success(TransactionView(duplicate));StockTransaction? issue=await db.StockTransactions.SingleOrDefaultAsync(x=>x.CompanyId==Company&&x.Id==c.OriginalIssueTransactionId&&x.TransactionType==StockTransactionType.Issue&&x.SourceType=="WAREHOUSE_ISSUE",t);if(issue is null)return Result.Failure<StockTransactionView>(InventoryErrors.NotFound);string uom=await Uom(issue.ProductVariantId,t);if(!string.IsNullOrWhiteSpace(c.UomCode)&&InventoryText.Code(c.UomCode)!=uom)return Result.Failure<StockTransactionView>(InventoryErrors.UnitMismatch);decimal returned=Math.Abs(await db.StockTransactions.Where(x=>x.SourceId==issue.Id&&x.TransactionType==StockTransactionType.Return).SumAsync(x=>(decimal?)x.QuantityDelta,t)??0);if(returned+c.Quantity>Math.Abs(issue.QuantityDelta))return Result.Failure<StockTransactionView>(InventoryErrors.Insufficient);StockBalance b=await GetOrCreateBalance(issue.WarehouseId,issue.ProductVariantId,t);Result applied=b.ApplyOnHand(c.Quantity,false,Now);if(applied.IsFailure)return Result.Failure<StockTransactionView>(applied.Error);Result<StockTransaction> made=StockTransaction.Create(Company,issue.WarehouseId,issue.ProductVariantId,StockTransactionType.Return,c.Quantity,uom,"WAREHOUSE_RETURN",issue.Id,reference,"USABLE",Actor,Correlation,Now,Now);if(made.IsFailure)return Result.Failure<StockTransactionView>(made.Error);db.Add(made.Value);Log("inventory.stock.returned",made.Value.Id);return Result.Success(TransactionView(made.Value));},ct);
 public async Task<Result> ReleaseOrderReservationsInsideTransactionAsync(Guid orderId,CancellationToken t)
 {
  List<StockReservation> rows=await db.StockReservations.Where(x=>x.CompanyId==Company&&x.OrderItemId!=Guid.Empty&&db.OrderItems.Any(i=>i.Id==x.OrderItemId&&i.OrderId==orderId)&&(x.Status==ReservationStatus.Active||x.Status==ReservationStatus.PartiallyReleased)).OrderBy(x=>x.WarehouseId).ThenBy(x=>x.ProductVariantId).ThenBy(x=>x.Id).ToListAsync(t);foreach(StockReservation row in rows){StockBalance? b=await LockBalance(row.WarehouseId,row.ProductVariantId,t);if(b is null)return Result.Failure(InventoryErrors.NotFound);decimal q=row.RemainingQuantity;if(q<=0)continue;Result r=row.Release(q,row.Version,Now);if(r.IsFailure)return r;Result br=b.Release(q,Now);if(br.IsFailure)return br;Log("inventory.reservation.released",row.Id);}return Result.Success();
 }
 public Task<Result<int>>ExpireAsync(CancellationToken ct)=>tx.ExecuteAsync(async t=>{List<StockReservation>rows=await db.StockReservations.Where(x=>x.ExpiresAtUtc<=Now&&(x.Status==ReservationStatus.Active||x.Status==ReservationStatus.PartiallyReleased)).ToListAsync(t);int count=0;foreach(StockReservation r in rows){StockBalance?b=await LockBalance(r.WarehouseId,r.ProductVariantId,t);decimal q=r.Expire(Now);if(q>0&&b is not null){b.Release(q,Now);Log("inventory.reservation.expired",r.Id);count++;}}return Result.Success(count);},ct);
 public Task<Result<TransferView>>TransferAsync(TransferCommand c,CancellationToken ct)=>tx.ExecuteAsync(async t=>{StockTransfer?duplicate=await db.StockTransfers.SingleOrDefaultAsync(x=>x.Reference==InventoryText.Code(c.Reference),t);if(duplicate is not null)return Result.Success(TransferView(duplicate));if(!await ValidWarehouseVariant(c.SourceWarehouseId,c.ProductVariantId,t)||!await ValidWarehouseVariant(c.DestinationWarehouseId,c.ProductVariantId,t))return Result.Failure<TransferView>(InventoryErrors.NotFound);Result<StockTransfer>made=StockTransfer.Create(Company,c.SourceWarehouseId,c.DestinationWarehouseId,c.ProductVariantId,c.Quantity,await Uom(c.ProductVariantId,t),c.Reference,Now);if(made.IsFailure)return Result.Failure<TransferView>(made.Error);StockBalance?source=await LockBalance(c.SourceWarehouseId,c.ProductVariantId,t);if(source is null)return Result.Failure<TransferView>(InventoryErrors.Insufficient);Result applied=source.ApplyOnHand(-c.Quantity,false,Now);if(applied.IsFailure)return Result.Failure<TransferView>(applied.Error);db.Add(made.Value);db.Add(StockTransaction.Create(Company,c.SourceWarehouseId,c.ProductVariantId,StockTransactionType.TransferOut,-c.Quantity,made.Value.UomCode,"TRANSFER",made.Value.Id,$"{made.Value.Reference}-OUT",null,Actor,Correlation,Now,Now).Value);Log("inventory.transfer.started",made.Value.Id);return Result.Success(TransferView(made.Value));},ct);
 public Task<Result<TransferView>>CompleteTransferAsync(Guid id,CompleteTransferCommand c,CancellationToken ct)=>tx.ExecuteAsync(async t=>{StockTransfer?x=await db.StockTransfers.SingleOrDefaultAsync(x=>x.Id==id,t);if(x is null)return Result.Failure<TransferView>(InventoryErrors.NotFound);if(x.Status==StockTransferStatus.Completed)return Result.Success(TransferView(x));Result done=x.Complete(c.Version,Now);if(done.IsFailure)return Result.Failure<TransferView>(done.Error);StockBalance b=await GetOrCreateBalance(x.DestinationWarehouseId,x.ProductVariantId,t);b.ApplyOnHand(x.Quantity,false,Now);db.Add(StockTransaction.Create(Company,x.DestinationWarehouseId,x.ProductVariantId,StockTransactionType.TransferIn,x.Quantity,x.UomCode,"TRANSFER",x.Id,$"{x.Reference}-IN",null,Actor,Correlation,Now,Now).Value);Log("inventory.transfer.completed",x.Id);return Result.Success(TransferView(x));},ct);
 public Task<Result<PurchaseRequestView>>CreateRequestAsync(CreatePurchaseRequestCommand c,CancellationToken ct)=>tx.ExecuteAsync(async t=>{if(!await db.Warehouses.AnyAsync(x=>x.Id==c.WarehouseId&&x.IsActive,t)||c.Items.Count==0||c.Items.Any(x=>x.Quantity<=0))return Result.Failure<PurchaseRequestView>(InventoryErrors.InvalidData);if(c.SourceShortageId is not null&&!await db.StockShortages.AnyAsync(x=>x.Id==c.SourceShortageId&&x.IsActive,t))return Result.Failure<PurchaseRequestView>(InventoryErrors.NotFound);Result<PurchaseRequest>made=PurchaseRequest.Create(Company,c.WarehouseId,Actor,c.Reason,c.SourceShortageId,Now);if(made.IsFailure)return Result.Failure<PurchaseRequestView>(made.Error);foreach(var i in c.Items){if(!await db.ProductVariants.AnyAsync(x=>x.Id==i.ProductVariantId&&x.IsActive,t))return Result.Failure<PurchaseRequestView>(InventoryErrors.NotFound);string uom=await Uom(i.ProductVariantId,t);if(!string.IsNullOrWhiteSpace(i.UomCode)&&!string.Equals(InventoryText.Code(i.UomCode),uom,StringComparison.OrdinalIgnoreCase))return Result.Failure<PurchaseRequestView>(InventoryErrors.UnitMismatch);db.Add(PurchaseRequestItem.Create(Company,made.Value.Id,i.ProductVariantId,uom,i.Quantity));}db.Add(made.Value);History("PURCHASE_REQUEST",made.Value.Id,"Created",c.Reason);Log("purchasing.request.created",made.Value.Id);return Result.Success(RequestView(made.Value));},ct);
 public Task<Result<IReadOnlyList<PurchaseRequestListView>>>ListRequestsAsync(CancellationToken ct)=>tx.ExecuteAsync(async t=>{List<PurchaseRequest> requests=await db.PurchaseRequests.AsNoTracking().OrderByDescending(x=>x.CreatedAtUtc).Take(100).ToListAsync(t);Dictionary<Guid,string> warehouses=await db.Warehouses.AsNoTracking().ToDictionaryAsync(x=>x.Id,x=>$"{x.Code} - {x.Name}",t);Dictionary<Guid,int> counts=await db.PurchaseRequestItems.AsNoTracking().Where(x=>requests.Select(r=>r.Id).Contains(x.PurchaseRequestId)).GroupBy(x=>x.PurchaseRequestId).ToDictionaryAsync(g=>g.Key,g=>g.Count(),t);return Result.Success<IReadOnlyList<PurchaseRequestListView>>(requests.Select(x=>new PurchaseRequestListView(x.Id,x.RequestNumber,x.WarehouseId,warehouses.GetValueOrDefault(x.WarehouseId,""),x.Reason,counts.GetValueOrDefault(x.Id),x.Status,x.CreatedAtUtc,x.Version)).ToArray());},ct);
 public Task<Result<PurchaseRequestDetailView>>GetRequestAsync(Guid id,CancellationToken ct)=>tx.ExecuteAsync(async t=>{PurchaseRequest? request=await db.PurchaseRequests.AsNoTracking().SingleOrDefaultAsync(x=>x.Id==id,t);if(request is null)return Result.Failure<PurchaseRequestDetailView>(InventoryErrors.NotFound);List<PurchaseRequestItemView> items=await db.PurchaseRequestItems.AsNoTracking().Where(x=>x.PurchaseRequestId==id).Select(x=>new PurchaseRequestItemView(x.Id,x.ProductVariantId,x.RequestedQuantity,x.UomCode)).ToListAsync(t);return Result.Success(new PurchaseRequestDetailView(request.Id,request.RequestNumber,request.WarehouseId,request.Reason,request.SourceShortageId,request.Status,request.Version,items));},ct);
 public Task<Result<PurchaseRequestView>>SubmitRequestAsync(Guid id,long version,CancellationToken ct)=>tx.ExecuteAsync(async t=>{PurchaseRequest?x=await db.PurchaseRequests.SingleOrDefaultAsync(x=>x.Id==id,t);if(x is null)return Result.Failure<PurchaseRequestView>(InventoryErrors.NotFound);Result r=x.Submit(version,Now);if(r.IsFailure)return Result.Failure<PurchaseRequestView>(r.Error);History("PURCHASE_REQUEST",id,"Submitted",null);Log("purchasing.request.submitted",id);return Result.Success(RequestView(x));},ct);
 public Task<Result<PurchaseOrderView>>CreateOrderAsync(CreatePurchaseOrderCommand c,CancellationToken ct)=>tx.ExecuteAsync(async t=>{if(c.Items.Count==0||c.Items.Any(x=>x.Quantity<=0||x.UnitPurchasePrice<0)||c.CurrencyCode.Trim().Length!=3||!await db.Suppliers.AnyAsync(x=>x.Id==c.SupplierId&&x.IsActive,t)||!await db.Warehouses.AnyAsync(x=>x.Id==c.WarehouseId&&x.IsActive,t))return Result.Failure<PurchaseOrderView>(InventoryErrors.InvalidData);await using var command=db.Database.GetDbConnection().CreateCommand();command.CommandText="SELECT nextval('barang.purchase_order_number_seq')";command.Transaction=db.Database.CurrentTransaction!.GetDbTransaction();long seq=Convert.ToInt64(await command.ExecuteScalarAsync(t),System.Globalization.CultureInfo.InvariantCulture);PurchaseOrder po=PurchaseOrder.Create(Company,c.SupplierId,c.WarehouseId,$"PO-{Now.Year}-{seq:0000000000}",c.CurrencyCode,c.ExpectedDeliveryDate,Now);db.Add(po);foreach(var i in c.Items){if(!await db.ProductVariants.AnyAsync(x=>x.Id==i.ProductVariantId&&x.IsActive,t))return Result.Failure<PurchaseOrderView>(InventoryErrors.NotFound);string uom=await Uom(i.ProductVariantId,t);if(!string.IsNullOrWhiteSpace(i.UomCode)&&!string.Equals(InventoryText.Code(i.UomCode),uom,StringComparison.OrdinalIgnoreCase))return Result.Failure<PurchaseOrderView>(InventoryErrors.UnitMismatch);db.Add(PurchaseOrderItem.Create(Company,po.Id,i.ProductVariantId,uom,i.Quantity,i.UnitPurchasePrice));}History("PURCHASE_ORDER",po.Id,"Created",po.PurchaseOrderNumber);Log("purchasing.order.created",po.Id);return Result.Success(await PurchaseOrderView(po,t));},ct);
 public Task<Result<PurchaseOrderView>>SubmitOrderAsync(Guid id,long version,CancellationToken ct)=>tx.ExecuteAsync(async t=>{PurchaseOrder?po=await db.PurchaseOrders.SingleOrDefaultAsync(x=>x.Id==id,t);if(po is null)return Result.Failure<PurchaseOrderView>(InventoryErrors.NotFound);Result r=po.Submit(version,Now);if(r.IsFailure)return Result.Failure<PurchaseOrderView>(r.Error);History("PURCHASE_ORDER",id,"Submitted",null);Log("purchasing.order.submitted",id);return Result.Success(await PurchaseOrderView(po,t));},ct);
 public Task<Result<PurchaseOrderView>>ReceiveAsync(Guid id,PurchaseReceiptCommand c,CancellationToken ct)=>tx.ExecuteAsync(async t=>{PurchaseOrder?po=await db.PurchaseOrders.SingleOrDefaultAsync(x=>x.Id==id,t);if(po is null)return Result.Failure<PurchaseOrderView>(InventoryErrors.NotFound);if(po.Status is not(PurchaseOrderStatus.Submitted or PurchaseOrderStatus.PartiallyReceived))return Result.Failure<PurchaseOrderView>(InventoryErrors.InvalidTransition);PurchaseReceipt?duplicate=await db.PurchaseReceipts.SingleOrDefaultAsync(x=>x.Reference==InventoryText.Code(c.Reference),t);if(duplicate is not null)return Result.Success(await PurchaseOrderView(po,t));PurchaseOrderItem?item=await db.PurchaseOrderItems.SingleOrDefaultAsync(x=>x.Id==c.PurchaseOrderItemId&&x.PurchaseOrderId==id,t);if(item is null||c.Quantity<=0)return Result.Failure<PurchaseOrderView>(InventoryErrors.InvalidData);decimal received=await db.PurchaseReceipts.Where(x=>x.PurchaseOrderItemId==item.Id).SumAsync(x=>(decimal?)x.Quantity,t)??0;if(received+c.Quantity>item.OrderedQuantity)return Result.Failure<PurchaseOrderView>(InventoryErrors.OverReceipt);StockMovementCommand movement=new(po.WarehouseId,item.ProductVariantId,c.Quantity,$"PO-{c.Reference}","PURCHASE_RECEIPT",Now);Result<StockTransactionView>mr=await Movement(movement,StockTransactionType.Receipt,c.Quantity,false,"PURCHASE_ORDER",po.Id,t);if(mr.IsFailure)return Result.Failure<PurchaseOrderView>(mr.Error);db.Add(PurchaseReceipt.Create(Company,po.Id,item.Id,mr.Value.Id,c.Quantity,c.Reference,Actor,Now));List<PurchaseOrderItem>items=await db.PurchaseOrderItems.Where(x=>x.PurchaseOrderId==id).ToListAsync(t);bool complete=true;foreach(PurchaseOrderItem i in items){decimal q=await db.PurchaseReceipts.Where(x=>x.PurchaseOrderItemId==i.Id).SumAsync(x=>(decimal?)x.Quantity,t)??0;if(i.Id==item.Id)q+=c.Quantity;if(q<i.OrderedQuantity)complete=false;}po.MarkReceipt(complete,Now);History("PURCHASE_ORDER",id,complete?"Received":"PartiallyReceived",c.Reference);Log("purchasing.receipt.created",mr.Value.Id);return Result.Success(await PurchaseOrderView(po,t));},ct);
 public Task<Result<PurchaseOrderView>>CloseAsync(Guid id,ClosePurchaseOrderCommand c,CancellationToken ct)=>tx.ExecuteAsync(async t=>{PurchaseOrder?po=await db.PurchaseOrders.SingleOrDefaultAsync(x=>x.Id==id,t);if(po is null)return Result.Failure<PurchaseOrderView>(InventoryErrors.NotFound);Result r=po.Close(c.Cancel,c.Reason,c.Version,Now);if(r.IsFailure)return Result.Failure<PurchaseOrderView>(r.Error);History("PURCHASE_ORDER",id,c.Cancel?"Cancelled":"Closed",c.Reason);Log(c.Cancel?"purchasing.order.cancelled":"purchasing.order.closed",id);return Result.Success(await PurchaseOrderView(po,t));},ct);
 public Task<Result<IReadOnlyList<PurchaseOrderView>>>ListOrdersAsync(CancellationToken ct)=>tx.ExecuteAsync(async t=>{List<PurchaseOrderView>result=[];foreach(PurchaseOrder po in await db.PurchaseOrders.AsNoTracking().OrderByDescending(x=>x.CreatedAtUtc).Take(100).ToListAsync(t))result.Add(await PurchaseOrderView(po,t));return Result.Success<IReadOnlyList<PurchaseOrderView>>(result);},ct);
 private async Task<Result<StockTransactionView>>Movement(StockMovementCommand c,StockTransactionType type,decimal delta,bool allowNegative,string source,Guid?sourceId,CancellationToken t){if(c.Quantity<=0||!await ValidWarehouseVariant(c.WarehouseId,c.ProductVariantId,t))return Result.Failure<StockTransactionView>(InventoryErrors.InvalidData);string uom=await Uom(c.ProductVariantId,t);if(!string.IsNullOrWhiteSpace(c.UomCode)&&!string.Equals(InventoryText.Code(c.UomCode),uom,StringComparison.OrdinalIgnoreCase))return Result.Failure<StockTransactionView>(InventoryErrors.UnitMismatch);string reference=InventoryText.Code(c.Reference);StockTransaction?existing=await db.StockTransactions.SingleOrDefaultAsync(x=>x.Reference==reference,t);if(existing is not null)return Result.Success(TransactionView(existing));StockBalance b=await GetOrCreateBalance(c.WarehouseId,c.ProductVariantId,t);Result applied=b.ApplyOnHand(delta,allowNegative,Now);if(applied.IsFailure)return Result.Failure<StockTransactionView>(applied.Error);StockTransaction st=StockTransaction.Create(Company,c.WarehouseId,c.ProductVariantId,type,delta,uom,source,sourceId,reference,c.ReasonCode,Actor,Correlation,c.OccurredAtUtc??Now,Now).Value;db.Add(st);Log(type==StockTransactionType.Receipt?"inventory.stock.received":"inventory.stock.changed",st.Id);return Result.Success(TransactionView(st));}
 private async Task<StockBalance>GetOrCreateBalance(Guid warehouse,Guid variant,CancellationToken t){StockBalance?b=await LockBalance(warehouse,variant,t);if(b is not null)return b;b=StockBalance.Create(Company,warehouse,variant,Now);db.Add(b);return b;}private async Task<StockBalance?>LockBalance(Guid warehouse,Guid variant,CancellationToken t){await db.Database.ExecuteSqlInterpolatedAsync($"SELECT id FROM barang.stock_balances WHERE company_id={Company} AND warehouse_id={warehouse} AND product_variant_id={variant} FOR UPDATE",t);return await db.StockBalances.SingleOrDefaultAsync(x=>x.WarehouseId==warehouse&&x.ProductVariantId==variant,t);}private async Task<StockReservation?>LockReservation(Guid id,CancellationToken t){await db.Database.ExecuteSqlInterpolatedAsync($"SELECT id FROM barang.stock_reservations WHERE company_id={Company} AND id={id} FOR UPDATE",t);return await db.StockReservations.SingleOrDefaultAsync(x=>x.CompanyId==Company&&x.Id==id,t);}private async Task<StockReservation?>LockReservationForOrder(Guid item,Guid order,Guid warehouse,CancellationToken t){await db.Database.ExecuteSqlInterpolatedAsync($"SELECT r.id FROM barang.stock_reservations r JOIN barang.order_items i ON i.id=r.order_item_id AND i.company_id=r.company_id WHERE r.company_id={Company} AND r.order_item_id={item} AND i.order_id={order} AND r.warehouse_id={warehouse} FOR UPDATE",t);return await db.StockReservations.SingleOrDefaultAsync(x=>x.CompanyId==Company&&x.OrderItemId==item&&x.WarehouseId==warehouse&&db.OrderItems.Any(i=>i.Id==item&&i.OrderId==order),t);}private async Task<bool>ValidWarehouseVariant(Guid warehouse,Guid variant,CancellationToken t)=>await db.Warehouses.AnyAsync(x=>x.CompanyId==Company&&x.Id==warehouse&&x.IsActive,t)&&await db.ProductVariants.AnyAsync(x=>x.CompanyId==Company&&x.Id==variant&&x.IsActive,t);private async Task<string>Uom(Guid variant,CancellationToken t)=>await(from v in db.ProductVariants join p in db.Products on v.ProductId equals p.Id where v.CompanyId==Company&&p.CompanyId==Company&&v.Id==variant select p.UnitOfMeasureCode).SingleAsync(t);
 private void Log(string action,Guid id)=>audit.Write(new(action,"inventory",id.ToString(),ChangeKind:AuditChangeKind.Modified));private void History(string entity,Guid id,string type,string?summary)=>db.PurchasingHistory.Add(PurchasingHistory.Create(Company,entity,id,type,Actor,Now,summary));private static StockBalanceView BalanceView(StockBalance x)=>new(x.WarehouseId,x.ProductVariantId,x.OnHand,x.Reserved,x.Available,x.Version);private static StockTransactionView TransactionView(StockTransaction x)=>new(x.Id,x.WarehouseId,x.ProductVariantId,x.TransactionType,x.QuantityDelta,x.UomCode,x.SourceType,x.SourceId,x.Reference,x.OccurredAtUtc);private static ReservationView ReservationView(StockReservation x)=>new(x.Id,x.OrderItemId,x.WarehouseId,x.ProductVariantId,x.UomCode,x.RequestedQuantity,x.ReservedQuantity,x.RemainingQuantity,x.Status,x.ExpiresAtUtc,x.Version);private static TransferView TransferView(StockTransfer x)=>new(x.Id,x.SourceWarehouseId,x.DestinationWarehouseId,x.ProductVariantId,x.Quantity,x.Status,x.Version);private static PurchaseRequestView RequestView(PurchaseRequest x)=>new(x.Id,x.WarehouseId,x.Reason,x.Status,x.Version);private async Task<PurchaseOrderView>PurchaseOrderView(PurchaseOrder po,CancellationToken t){List<PurchaseOrderItem>items=await db.PurchaseOrderItems.AsNoTracking().Where(x=>x.PurchaseOrderId==po.Id).ToListAsync(t);items.AddRange(db.PurchaseOrderItems.Local.Where(x=>x.PurchaseOrderId==po.Id&&!items.Any(y=>y.Id==x.Id)));List<PurchaseReceipt>receipts=await db.PurchaseReceipts.AsNoTracking().Where(x=>x.PurchaseOrderId==po.Id).ToListAsync(t);receipts.AddRange(db.PurchaseReceipts.Local.Where(x=>x.PurchaseOrderId==po.Id&&!receipts.Any(y=>y.Id==x.Id)));return new(po.Id,po.PurchaseOrderNumber,po.SupplierId,po.WarehouseId,po.CurrencyCode,po.Status,po.Version,items.Select(i=>new PurchaseOrderItemView(i.Id,i.ProductVariantId,i.UomCode,i.OrderedQuantity,receipts.Where(r=>r.PurchaseOrderItemId==i.Id).Sum(r=>r.Quantity),i.UnitPurchasePrice)).ToArray());}
